use std::path::{Path, PathBuf};

pub const APP_EXE_NAME: &str = "yaz.exe";
pub const UPDATER_EXE_NAME: &str = "yaz-updater.exe";

/// File manifest in the app directory (sha256sum format, generated by tools/pack-release.ps1); an
/// update touches only the files listed in the manifest.
pub const FILE_LIST_NAME: &str = "yaz.files.sha256";

/// Directory holding the old files during replacement, inside the app directory: moving files is
/// fast and needs no write permission on the parent directory.
pub const BACKUP_DIR_NAME: &str = ".update-backup";

/// Argument when the updater starts the new version, followed by the path of the start marker;
/// after the new version starts successfully it writes its version number to that file.
pub const PROBE_ARG: &str = "--update-probe";

/// Locations of the files in the update working directory.
#[derive(Debug, Clone)]
pub struct UpdateLayout {
    root: PathBuf,
}

impl UpdateLayout {
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    /// `%LOCALAPPDATA%\YaZ.Update`
    pub fn default_root() -> PathBuf {
        std::env::var_os("LOCALAPPDATA")
            .map_or_else(std::env::temp_dir, PathBuf::from)
            .join("YaZ.Update")
    }

    pub fn root(&self) -> &Path {
        &self.root
    }

    pub fn state_path(&self) -> PathBuf {
        self.root.join("state.json")
    }

    /// The new version that has been downloaded, verified and extracted, awaiting replacement.
    pub fn staged_dir(&self) -> PathBuf {
        self.root.join("staged")
    }

    /// Manifest written once extraction is in place; its existence means `staged_dir` is complete
    /// and usable.
    pub fn ready_path(&self) -> PathBuf {
        self.root.join("ready.json")
    }

    /// Temporary directory for download and extraction.
    pub fn work_dir(&self) -> PathBuf {
        self.root.join("work")
    }

    /// Directory holding the updater's runtime copy: the updater replaces the app directory, so it
    /// cannot run from inside it.
    pub fn runner_dir(&self) -> PathBuf {
        self.root.join("runner")
    }

    /// Marker written after the new version starts successfully.
    pub fn probe_path(&self) -> PathBuf {
        self.root.join("started.txt")
    }
}
